// Alle Seiten zu einer Liste zusammenfuehren.
// Der HTTP-Node hat pro Seite ein Item geliefert, jedes mit einem data-Array.
const alle = [];
for (const seite of $input.all()) {
  for (const zeile of (seite.json.data || [])) alle.push(zeile);
}

// WICHTIG: auf eine positive Marke pruefen, nicht auf den Statuscode.
// Ein gruener Lauf mit 50 Zeilen sieht genauso aus wie einer mit 1631.
// Trage hier ein, wie viele Zeilen du mindestens erwartest.
const MINDESTENS = Number($('Konfiguration').first().json.mindestens) || 1;
if (alle.length < MINDESTENS) {
  throw new Error('Nur ' + alle.length + ' Zeilen geladen, erwartet waren mindestens '
    + MINDESTENS + '. Entweder ist die Tabelle kleiner als gedacht, oder es greift'
    + ' ein stiller Zeilendeckel.');
}

return [{ json: {
  seiten_geholt: $input.all().length,
  zeilen_gesamt: alle.length,
  erste_zeile: alle[0] || null,
  letzte_zeile: alle[alle.length - 1] || null
} }];
